import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>();
        list.add(5);
        list.add(7);
        int sum = 0;
        for (int n : list) {
            sum += n;
        }
        System.out.println(sum);
    }
}
